 {\CC_{j,\pi}(n)}/{n} \leq c^0_{j}, \ \ \forall  j=1,\ldots,L, \ \forall n=1,2,\ldots
\end{equation}

source.quote:
If $\pi$ is an f-UF policy then
\begin{equation}
\lowlim_{n\rightarrow\infty}\frac{R_{\pi}(\underline{\underline{\theta}},n)}{\log
n}\geq M(\underline{\underline{\theta}}), \ \forall
\underline{\underline{\theta}}\in\Theta.\nonumber
\end{equation}

Under conditions (C1),(C2), and (C3), and  policy $\pi^0$, defined above,  the following holds.
\begin{equation}
\uplim_{n\rightarrow\infty}\frac{R_{\pi^0}(\underline{\underline{\theta}},n)}{\log
n}\leq M(\underline{\underline{\theta}}), \text{ for all }
\underline{\underline{\theta}}\in\Theta.\nonumber
\end{equation}
